import sqlite3

DB_PATH = "var/catalog.sqlite3"

def asset_record(asset_id: str):
    with sqlite3.connect(DB_PATH) as db:
        return db.execute("select path, sha256 from assets where asset_id = ?", (asset_id,)).fetchone()

from pathlib import Path

def delivered(page: Path, delivery_id: str) -> bool:
    return f'data-delivery-id="{delivery_id}"' in page.read_text(encoding="utf-8")

import sqlite3
DB_PATH = "var/app.sqlite3"

def readback(job_id: str):
    with sqlite3.connect(DB_PATH) as db:
        return db.execute("select value from results where job_id = ?", (job_id,)).fetchone()

def status_endpoint(job_id, cache):
    return cache.get(job_id)

def durable_readback(job_id, store):
    return store.get(job_id)

def _persist_value(store, job_id, value):
    store[job_id] = value

def complete(store, job_id, value):
    _persist_value(store, job_id, value)
    return store[job_id]

def migrate(db):
    db.execute("drop table old_results")
    db.execute("create table new_results(id text primary key, value text not null)")
